// @generated by project-forge — visual-layout.mjs (pure deterministic SVG/HTML layout model)
import { buildFallbackDomains } from './feature-map-graph.mjs'

export const DIFF_STATES = Object.freeze(['added', 'modified', 'removed', 'impacted', 'context'])

const DOMAIN_PALETTES = Object.freeze([
  { id: 'teal', stroke: '#1b5e6b', fill: 'rgba(27,94,107,0.045)', badge: '#1b5e6b' },
  { id: 'moss', stroke: '#3f6a4f', fill: 'rgba(63,106,79,0.045)', badge: '#3f6a4f' },
  { id: 'ochre', stroke: '#8c6239', fill: 'rgba(140,98,57,0.045)', badge: '#8c6239' },
  { id: 'steel', stroke: '#355c7d', fill: 'rgba(53,92,125,0.045)', badge: '#355c7d' },
  { id: 'plum', stroke: '#6b4c5b', fill: 'rgba(107,76,91,0.045)', badge: '#6b4c5b' },
  { id: 'sage', stroke: '#4b5c58', fill: 'rgba(75,92,88,0.045)', badge: '#4b5c58' },
])

function pickDomainPalette(id) {
  let h = 2166136261
  const s = String(id || 'core')
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i)
    h = Math.imul(h, 16777619)
  }
  return DOMAIN_PALETTES[(h >>> 0) % DOMAIN_PALETTES.length]
}

export function escapeHtml(value) {
  return String(value ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;')
}

export function escapeXml(value) { return escapeHtml(value) }

export function escapeJsonForScript(obj) {
  return JSON.stringify(obj).replace(/</g, '\\u003c').replace(/>/g, '\\u003e').replace(/&/g, '\\u0026').replace(/\u2028/g, '\\u2028').replace(/\u2029/g, '\\u2029')
}

export function toRelPath(rawPath) {
  let p = String(rawPath ?? '').trim()
  if (!p) return ''
  p = p.replace(/^file:\/\/\/?/i, '').replace(/\\/g, '/')
  p = p.replace(/^[a-zA-Z]:\/(?:Users|Documents and Settings)\/[^/]+\//i, '')
  p = p.replace(/^\/(?:Users|home)\/[^/]+\//i, '')
  return p.replace(/^[a-zA-Z]:\//, '').replace(/^\/+/, '').replace(/^\.\//, '')
}

export function sanitizeSafeHref(rawUrl) {
  const s = String(rawUrl ?? '').trim()
  if (!s) return ''
  const compact = s.replace(/[\u0000-\u0020]+/g, '')
  const schemeMatch = /^([a-zA-Z][a-zA-Z0-9+.-]*):/.exec(compact)
  if (!schemeMatch) {
    if (compact.startsWith('//')) return ''
    return toRelPath(s) || s
  }
  const scheme = schemeMatch[1].toLowerCase()
  if (scheme === 'http' || scheme === 'https' || scheme === 'file') return s
  return ''
}

export function sanitizeSafeImgSrc(rawSrc) {
  const s = String(rawSrc ?? '').trim()
  if (!s) return ''
  const compact = s.replace(/[\u0000-\u0020]+/g, '')
  if (/^data:image\/(?:png|jpeg|jpg|webp|gif);base64,[a-zA-Z0-9+/=]+$/i.test(compact)) return compact
  return sanitizeSafeHref(s)
}

function normArray(list) {
  return Array.isArray(list) ? list.map((x) => String(x ?? '').trim()).filter(Boolean) : []
}

function normRelArray(list) {
  return normArray(list).map(toRelPath).filter(Boolean)
}

const FULLWIDTH_CHAR_RE = /[\u1100-\u115f\u2e80-\ua4cf\uac00-\ud7a3\uf900-\ufaff\ufe10-\ufe19\ufe30-\ufe6f\uff00-\uff60\uffe0-\uffe6]/

function displayWidth(text) {
  let w = 0
  for (const ch of String(text ?? '')) w += FULLWIDTH_CHAR_RE.test(ch) ? 2 : 1
  return w
}

export function truncateLabel(text, maxWidth = 28) {
  const s = String(text ?? '').trim()
  if (displayWidth(s) <= maxWidth) return s
  const budget = Math.max(4, maxWidth - 3)
  let acc = 0
  let out = ''
  for (const ch of s) {
    const w = FULLWIDTH_CHAR_RE.test(ch) ? 2 : 1
    if (acc + w > budget) break
    out += ch
    acc += w
  }
  return `${out}...`
}

function normalizeVerifyTools(rawTools) {
  if (!Array.isArray(rawTools)) return []
  return rawTools.map((t) => {
    if (typeof t === 'string') return t.trim()
    if (t && typeof t === 'object') {
      const id = String(t.id || t.name || '').trim()
      const cmd = String(t.command || t.scriptPath || '').trim()
      return id && cmd ? `${id}: ${cmd}` : (id || cmd)
    }
    return ''
  }).filter(Boolean)
}

function normalizeFeatures(featureMap) {
  const rawList = Array.isArray(featureMap?.features) ? featureMap.features : []
  return rawList.filter((f) => f && typeof f === 'object').map((f, idx) => {
    const id = String(f.id || `feature-${idx + 1}`).trim()
    const businessFlows = normArray(f.businessFlows)
    const description = String(f.description || f.summary || businessFlows[0] || '').trim()
    return {
      id,
      title: String(f.title || f.name || id).trim(),
      description,
      businessFlows,
      domain: String(f.domain || '').trim(),
      risk: String(f.risk || 'medium').trim().toLowerCase(),
      status: String(f.status || 'active').trim().toLowerCase(),
      entrypoints: normRelArray(f.entrypoints),
      modules: normRelArray(f.modules || f.files),
      tests: normRelArray(Array.isArray(f.tests) && f.tests.length > 0 ? f.tests : f.testRefs),
      symbols: normArray(f.symbols),
      verifyTools: normalizeVerifyTools(Array.isArray(f.verificationTools) && f.verificationTools.length > 0 ? f.verificationTools : f.verifyTools),
      docAnchors: normArray(f.docAnchors),
      dependsOn: normArray(f.dependsOn),
      actors: normArray(f.actors),
      anchorLine: Number.isFinite(Number(f.anchorLine)) ? Number(f.anchorLine) : 1,
      isVirtual: Boolean(f.isVirtual),
    }
  }).sort((a, b) => a.id.localeCompare(b.id))
}

function kahnTopoSort(ids, edgePairs, tieBreakCmp) {
  const uniqueIds = [...new Set(ids)]
  const idSet = new Set(uniqueIds)
  const rank = new Map(uniqueIds.map((id) => [id, 0]))
  const indeg = new Map(uniqueIds.map((id) => [id, 0]))
  const adj = new Map(uniqueIds.map((id) => [id, new Set()]))
  for (const [u, v] of edgePairs) {
    if (!idSet.has(u) || !idSet.has(v) || u === v || adj.get(u).has(v)) continue
    adj.get(u).add(v)
    indeg.set(v, (indeg.get(v) || 0) + 1)
  }
  const visited = new Set()
  const order = []
  while (visited.size < uniqueIds.length) {
    const ready = uniqueIds.filter((id) => !visited.has(id) && (indeg.get(id) || 0) <= 0).sort(tieBreakCmp)
    let cur
    if (ready.length > 0) {
      cur = ready[0]
    } else {
      const rem = uniqueIds.filter((id) => !visited.has(id)).sort((a, b) => ((indeg.get(a) || 0) - (indeg.get(b) || 0)) || tieBreakCmp(a, b))
      cur = rem[0]
    }
    visited.add(cur)
    order.push(cur)
    const curRank = rank.get(cur) || 0
    for (const nxt of adj.get(cur) || []) {
      if (visited.has(nxt)) continue
      rank.set(nxt, Math.max(rank.get(nxt) || 0, curRank + 1))
      indeg.set(nxt, Math.max(0, (indeg.get(nxt) || 0) - 1))
    }
  }
  return { rank, order }
}

function resolveDomains(featureMap, features) {
  const hasExplicit = Array.isArray(featureMap?.domains) && featureMap.domains.length > 0
  const fallback = hasExplicit ? null : buildFallbackDomains(features)
  const explicitDomains = hasExplicit
    ? featureMap.domains
    : (Array.isArray(fallback) ? fallback : (Array.isArray(fallback?.domains) ? fallback.domains : []))
  const domainMap = new Map()
  for (const d of explicitDomains) {
    if (!d || typeof d !== 'object') continue
    const id = String(d.id || 'core').trim()
    if (!id || domainMap.has(id)) continue
    const layer = d.layer !== undefined && d.layer !== null && d.layer !== '' && Number.isFinite(Number(d.layer)) ? Number(d.layer) : null
    domainMap.set(id, {
      id,
      title: String(d.title || d.name || id).trim(),
      description: String(d.description || '').trim(),
      risk: String(d.risk || 'medium').trim().toLowerCase(),
      owner: String(d.owner || '').trim(),
      layer,
      featureIds: normArray(d.features),
    })
  }
  const assigned = new Set()
  for (const f of features) {
    const domId = f.domain
      ? f.domain
      : (Array.from(domainMap.values()).find((d) => d.featureIds.includes(f.id))?.id || 'core')
    if (!domainMap.has(domId)) {
      domainMap.set(domId, {
        id: domId,
        title: domId,
        description: f.isVirtual ? '新增规划域' : 'Synthesized domain group',
        risk: 'medium',
        owner: '',
        layer: null,
        featureIds: [],
      })
    }
    const dom = domainMap.get(domId)
    if (!dom.featureIds.includes(f.id)) dom.featureIds.push(f.id)
    f.domain = domId
    assigned.add(f.id)
  }

  const active = Array.from(domainMap.values())
    .map((d) => ({ ...d, featureIds: d.featureIds.filter((fid) => assigned.has(fid)) }))
    .filter((d) => d.featureIds.length > 0 || explicitDomains.some((ed) => ed?.id === d.id))

  const featById = new Map(features.map((f) => [f.id, f]))
  const domEdges = []
  const crossDeg = new Map(active.map((d) => [d.id, 0]))
  const seenDomEdges = new Set()
  for (const f of features) {
    for (const depId of f.dependsOn) {
      const src = featById.get(depId)
      if (!src || !src.domain || !f.domain || src.domain === f.domain) continue
      const k = `${src.domain}->${f.domain}`
      if (seenDomEdges.has(k)) continue
      seenDomEdges.add(k)
      domEdges.push([src.domain, f.domain])
      crossDeg.set(src.domain, (crossDeg.get(src.domain) || 0) + 1)
      crossDeg.set(f.domain, (crossDeg.get(f.domain) || 0) + 1)
    }
  }
  const domById = new Map(active.map((d) => [d.id, d]))
  const { rank: domTier } = kahnTopoSort(
    active.map((d) => d.id),
    domEdges,
    (a, b) => ((crossDeg.get(b) || 0) - (crossDeg.get(a) || 0))
      || ((domById.get(b)?.featureIds.length || 0) - (domById.get(a)?.featureIds.length || 0))
      || a.localeCompare(b),
  )

  return active.map((d) => {
    const intraSet = new Set(d.featureIds)
    const intraEdges = []
    for (const fid of d.featureIds) {
      const f = featById.get(fid)
      if (!f) continue
      for (const dep of f.dependsOn) {
        if (intraSet.has(dep) && dep !== fid) intraEdges.push([dep, fid])
      }
    }
    const { order: sortedFids } = kahnTopoSort(d.featureIds, intraEdges, (a, b) => a.localeCompare(b))
    return {
      ...d,
      featureIds: sortedFids,
      effectiveLayer: d.layer !== null ? d.layer : (domTier.get(d.id) || 0),
      crossDeg: crossDeg.get(d.id) || 0,
      palette: pickDomainPalette(d.id),
    }
  }).sort((a, b) => (a.effectiveLayer - b.effectiveLayer)
    || (b.crossDeg - a.crossDeg)
    || (b.featureIds.length - a.featureIds.length)
    || a.id.localeCompare(b.id))
}

function makeVirtualFeature(raw, defaultDomain, isRemoved = false) {
  const id = String(raw?.id || '').trim()
  const desc = String(raw?.description || raw?.summary || raw?.reason || (isRemoved ? '拟移除模块' : '新增规划模块')).trim()
  return {
    id,
    title: String(raw?.title || raw?.name || id).trim(),
    description: desc,
    businessFlows: normArray(raw?.businessFlows),
    domain: String(raw?.domain || raw?.targetDomain || defaultDomain).trim() || defaultDomain,
    risk: String(raw?.risk || 'medium').trim().toLowerCase(),
    status: isRemoved ? 'removed' : 'planned',
    entrypoints: normRelArray(raw?.entrypoints),
    modules: normRelArray(raw?.modules),
    tests: normRelArray(raw?.tests),
    symbols: [],
    verifyTools: [],
    docAnchors: normArray(raw?.docAnchors),
    dependsOn: normArray(raw?.dependsOn),
    actors: normArray(raw?.actors),
    anchorLine: 1,
    isVirtual: true,
  }
}

export function computeDiffOverlay(featureMap, diffOverlay = {}) {
  const features = normalizeFeatures(featureMap)
  const featureById = new Map(features.map((f) => [f.id, f]))
  const states = new Map()
  const changeDetails = new Map()
  const directStates = diffOverlay?.featureStates && typeof diffOverlay.featureStates === 'object' ? diffOverlay.featureStates : {}
  const fcMap = diffOverlay?.featureChanges && typeof diffOverlay.featureChanges === 'object' ? diffOverlay.featureChanges : {}
  const addedSet = new Set(normArray(diffOverlay?.added))
  const modifiedSet = new Set(normArray(diffOverlay?.modified))
  const impactedSet = new Set(normArray(diffOverlay?.impacted))
  const removedSet = new Set()
  const changedFiles = new Set(normRelArray(diffOverlay?.changedFiles))

  for (const rawAdd of Array.isArray(diffOverlay?.addedNodes) ? diffOverlay.addedNodes : []) {
    const id = String(rawAdd?.id || '').trim()
    if (!id) continue
    addedSet.add(id)
    if (!featureById.has(id)) {
      const virt = makeVirtualFeature(rawAdd, 'planned', false)
      features.push(virt)
      featureById.set(id, virt)
    }
    changeDetails.set(id, {
      state: 'added',
      note: String(rawAdd?.summary || rawAdd?.description || '').trim(),
      before: '',
      after: String(rawAdd?.summary || rawAdd?.description || '').trim(),
      reason: String(rawAdd?.reason || '').trim(),
      replacementId: '',
    })
  }

  for (const rem of Array.isArray(diffOverlay?.removed) ? diffOverlay.removed : []) {
    const id = typeof rem === 'string' ? rem.trim() : String(rem?.id || '').trim()
    if (!id) continue
    removedSet.add(id)
    const reason = typeof rem === 'object' ? String(rem?.reason || '').trim() : ''
    const replacementId = typeof rem === 'object' ? String(rem?.replacementId || '').trim() : ''
    if (!featureById.has(id)) {
      const virt = makeVirtualFeature(typeof rem === 'object' ? rem : { id }, 'core', true)
      features.push(virt)
      featureById.set(id, virt)
    }
    changeDetails.set(id, { state: 'removed', note: reason, before: '', after: '', reason, replacementId })
  }

  for (const [fid, fc] of Object.entries(fcMap)) {
    if (!fc || typeof fc !== 'object') continue
    const st = DIFF_STATES.includes(fc.state) ? fc.state : (fc.reason || fc.replacementId ? 'removed' : 'modified')
    const prev = changeDetails.get(fid) || {}
    changeDetails.set(fid, {
      state: st,
      note: String(fc.note ?? prev.note ?? '').trim(),
      before: String(fc.before ?? prev.before ?? '').trim(),
      after: String(fc.after ?? prev.after ?? '').trim(),
      reason: String(fc.reason ?? prev.reason ?? '').trim(),
      replacementId: String(fc.replacementId ?? prev.replacementId ?? '').trim(),
    })
    if (st === 'removed') removedSet.add(fid)
    else if (st === 'added') addedSet.add(fid)
    else if (st === 'modified') modifiedSet.add(fid)
    if (!featureById.has(fid) && (st === 'added' || st === 'removed')) {
      const virt = makeVirtualFeature({ id: fid, domain: fc.targetDomain || fc.domain, summary: fc.note || fc.after || fc.reason }, st === 'added' ? 'planned' : 'core', st === 'removed')
      features.push(virt)
      featureById.set(fid, virt)
    }
  }

  for (const f of features) {
    let state = 'context'
    const explicit = directStates[f.id]
    const fcState = changeDetails.get(f.id)?.state
    if (DIFF_STATES.includes(explicit)) state = explicit
    else if (removedSet.has(f.id)) state = 'removed'
    else if (fcState && DIFF_STATES.includes(fcState)) state = fcState
    else if (addedSet.has(f.id)) state = 'added'
    else if (modifiedSet.has(f.id)) state = 'modified'
    else if (impactedSet.has(f.id)) state = 'impacted'
    else if (changedFiles.size > 0 && [...f.entrypoints, ...f.modules, ...f.tests].some((p) => changedFiles.has(p))) state = 'modified'
    states.set(f.id, state)
  }

  const dependents = new Map()
  for (const f of features) {
    for (const dep of f.dependsOn) {
      if (!dependents.has(dep)) dependents.set(dep, [])
      dependents.get(dep).push(f.id)
    }
  }

  const impactReasons = new Map()
  const seeds = features.filter((f) => {
    const st = states.get(f.id)
    return st === 'added' || st === 'modified' || st === 'removed'
  })
  for (const seed of seeds) {
    const seedState = states.get(seed.id)
    const reasonText = seedState === 'removed'
      ? `上游「${seed.title}」拟移除`
      : (seedState === 'added' ? `依赖新增「${seed.title}」` : `上游「${seed.title}」计划修改`)
    const queue = [seed.id]
    const seen = new Set(queue)
    while (queue.length > 0) {
      const cur = queue.shift()
      for (const nid of dependents.get(cur) || []) {
        if (seen.has(nid)) continue
        seen.add(nid)
        if (states.get(nid) === 'context') states.set(nid, 'impacted')
        if (!impactReasons.has(nid)) impactReasons.set(nid, [])
        const arr = impactReasons.get(nid)
        if (!arr.includes(reasonText)) arr.push(reasonText)
        queue.push(nid)
      }
    }
  }

  const counts = { added: 0, modified: 0, removed: 0, impacted: 0, context: 0 }
  for (const st of states.values()) counts[st] = (counts[st] || 0) + 1
  return {
    states,
    counts,
    hasActiveDiff: counts.added + counts.modified + counts.removed + counts.impacted > 0,
    features,
    changeDetails,
    impactReasons,
  }
}

export function layoutDomainTree(featureMap, overlay, _opts = {}) {
  const features = Array.isArray(overlay?.features) ? overlay.features : normalizeFeatures(featureMap)
  const domains = resolveDomains(featureMap, features)
  const featureById = new Map(features.map((f) => [f.id, f]))
  const stateMap = overlay?.states instanceof Map ? overlay.states : new Map()
  const detailMap = overlay?.changeDetails instanceof Map ? overlay.changeDetails : new Map()
  const reasonMap = overlay?.impactReasons instanceof Map ? overlay.impactReasons : new Map()

  const cardW = 284, cardH = 114, cardGapX = 24, cardGapY = 22
  const domPadX = 24, domPadBottom = 24, domGapX = 34, domGapY = 34, canvasPad = 32
  const domCols = domains.length <= 1 ? 1 : domains.length <= 4 ? 2 : 3
  const domainBoxes = [], featureBoxes = [], featureBoxMap = new Map()

  const preppedDomains = domains.map((dom) => {
    const items = dom.featureIds.map((fid) => featureById.get(fid)).filter(Boolean)
    const innerCols = items.length <= 1 ? 1 : Math.min(2, items.length)
    const rows = Math.max(1, Math.ceil(items.length / innerCols))
    const domHeaderH = (dom.description || displayWidth(dom.title) > 24) ? 66 : 54
    const w = domPadX * 2 + innerCols * cardW + Math.max(0, innerCols - 1) * cardGapX
    const h = domHeaderH + rows * cardH + Math.max(0, rows - 1) * cardGapY + domPadBottom
    return { dom, items, innerCols, domHeaderH, w, h }
  })

  const colWidths = Array.from({ length: domCols }, () => 0)
  preppedDomains.forEach((pd, idx) => { colWidths[idx % domCols] = Math.max(colWidths[idx % domCols], pd.w) })
  const rowHeights = []
  preppedDomains.forEach((pd, idx) => { rowHeights[Math.floor(idx / domCols)] = Math.max(rowHeights[Math.floor(idx / domCols)] || 0, pd.h) })

  const colOffsets = []
  let accX = canvasPad
  for (let c = 0; c < domCols; c++) { colOffsets[c] = accX; accX += colWidths[c] + domGapX }
  const rowOffsets = []
  let accY = canvasPad
  for (let r = 0; r < rowHeights.length; r++) { rowOffsets[r] = accY; accY += rowHeights[r] + domGapY }

  preppedDomains.forEach((pd, idx) => {
    const col = idx % domCols
    const row = Math.floor(idx / domCols)
    const x = colOffsets[col]
    const y = rowOffsets[row]
    const w = colWidths[col]
    const h = pd.h
    domainBoxes.push({
      id: pd.dom.id, title: pd.dom.title, shortTitle: truncateLabel(pd.dom.title, 34),
      description: pd.dom.description, shortDescription: pd.dom.description ? truncateLabel(pd.dom.description, 44) : '',
      domHeaderH: pd.domHeaderH, risk: pd.dom.risk, layer: pd.dom.effectiveLayer, palette: pd.dom.palette,
      x, y, w, h, featureCount: pd.items.length,
    })

    pd.items.forEach((feat, fIdx) => {
      const fCol = fIdx % pd.innerCols, fRow = Math.floor(fIdx / pd.innerCols)
      const fx = x + domPadX + fCol * (cardW + cardGapX), fy = y + pd.domHeaderH + fRow * (cardH + cardGapY)
      const diffState = stateMap.get(feat.id) || 'context'
      const primaryAnchor = feat.entrypoints[0] || feat.modules[0] || feat.tests[0] || ''
      const summarySrc = feat.description || feat.businessFlows[0] || toRelPath(primaryAnchor) || feat.id
      const box = {
        ...feat, shortTitle: truncateLabel(feat.title, 34), shortSummary: truncateLabel(summarySrc, 38),
        shortAnchor: truncateLabel(toRelPath(primaryAnchor) || feat.id, 36), domainTitle: pd.dom.title,
        x: fx, y: fy, w: cardW, h: cardH, cx: fx + cardW / 2, cy: fy + cardH / 2,
        diffState, isVirtual: Boolean(feat.isVirtual), changeDetail: detailMap.get(feat.id) || null,
        impactReasons: reasonMap.get(feat.id) || [], primaryAnchor, palette: pd.dom.palette,
      }
      featureBoxes.push(box); featureBoxMap.set(feat.id, box)
    })
  })

  const edges = []
  for (const feat of featureBoxes) {
    for (const depId of feat.dependsOn) {
      const src = featureBoxMap.get(depId)
      if (!src || src.id === feat.id) continue
      const x1 = src.x + src.w
      const y1 = src.cy
      const x2 = feat.x
      const y2 = feat.cy
      const sameColRightToLeft = Math.abs(src.x - feat.x) < 10
      let pathD
      if (sameColRightToLeft) {
        const sy1 = src.y + src.h
        const sy2 = feat.y
        const midY = (sy1 + sy2) / 2
        pathD = `M ${src.cx} ${sy1} C ${src.cx} ${midY}, ${feat.cx} ${midY}, ${feat.cx} ${sy2}`
      } else if (src.x <= feat.x) {
        const dx = Math.max(40, Math.abs(x2 - x1) * 0.45)
        pathD = `M ${x1} ${y1} C ${x1 + dx} ${y1}, ${x2 - dx} ${y2}, ${x2} ${y2}`
      } else {
        const sx1 = src.x
        const sx2 = feat.x + feat.w
        const dx = Math.max(40, Math.abs(sx2 - sx1) * 0.45)
        pathD = `M ${sx1} ${y1} C ${sx1 - dx} ${y1}, ${sx2 + dx} ${y2}, ${sx2} ${y2}`
      }
      const isVirtual = Boolean(src.isVirtual || feat.isVirtual)
      const edgeState = (src.diffState === 'added' || feat.diffState === 'added')
        ? 'added'
        : ((src.diffState === 'removed' || feat.diffState === 'removed')
            ? 'removed'
            : ((src.diffState !== 'context' || feat.diffState !== 'context') ? 'impacted' : 'context'))
      edges.push({
        id: `${src.id}->${feat.id}`,
        fromId: src.id,
        toId: feat.id,
        pathD,
        edgeState,
        isVirtual,
        impacted: edgeState !== 'context',
      })
    }
  }

  return {
    width: Math.max(640, accX - domGapX + canvasPad),
    height: Math.max(360, accY - domGapY + canvasPad),
    domains: domainBoxes,
    nodes: featureBoxes,
    edges,
  }
}

export function layoutFlowDag(featureMap, overlay, _opts = {}) {
  const features = Array.isArray(overlay?.features) ? overlay.features : normalizeFeatures(featureMap)
  const domains = resolveDomains(featureMap, features)
  const stateMap = overlay?.states instanceof Map ? overlay.states : new Map()
  const rawFlows = Array.isArray(featureMap?.flows) ? featureMap.flows : []

  const laneSpecs = []
  const flowSummaries = []
  if (rawFlows.length > 0) {
    const laneNames = new Map()
    for (const fl of rawFlows) {
      if (!fl || typeof fl !== 'object') continue
      const flowId = String(fl.id || `flow-${flowSummaries.length + 1}`).trim()
      const flowTitle = String(fl.title || fl.name || flowId).trim()
      const steps = Array.isArray(fl.steps) ? fl.steps : []
      const cleanSteps = steps.map((step, sIdx) => ({
        stepIndex: sIdx + 1,
        feature: String(step?.feature || '').trim(),
        actor: String(step?.actor || step?.lane || 'system').trim(),
        action: String(step?.action || '').trim(),
      })).filter((s) => s.feature)
      flowSummaries.push({
        id: flowId,
        title: flowTitle,
        description: String(fl.description || '').trim(),
        stepCount: cleanSteps.length,
        actors: normArray(fl.actors),
        featureIds: normArray(fl.features),
        steps: cleanSteps,
      })
      for (const step of steps) {
        const actor = String(step?.actor || step?.lane || 'system').trim()
        if (!laneNames.has(actor)) laneNames.set(actor, { id: actor, title: actor, palette: pickDomainPalette(actor) })
      }
    }
    for (const l of laneNames.values()) laneSpecs.push(l)
  }

  if (laneSpecs.length === 0) {
    for (const d of domains) laneSpecs.push({ id: d.id, title: d.title, palette: d.palette })
  }
  if (laneSpecs.length === 0) laneSpecs.push({ id: 'core', title: 'Core Pipeline', palette: DOMAIN_PALETTES[0] })

  const featureIds = new Set(features.map((f) => f.id))
  const edgePairs = []
  for (const f of features) {
    for (const dep of f.dependsOn) {
      if (featureIds.has(dep) && dep !== f.id) edgePairs.push([dep, f.id])
    }
  }
  const { rank: ranks } = kahnTopoSort(features.map((f) => f.id), edgePairs, (a, b) => a.localeCompare(b))
  const maxRank = Math.max(0, ...Array.from(ranks.values()))

  const labelColW = 172, nodeW = 200, nodeH = 74, colGap = 54, nodeGapY = 16, lanePadY = 18, pad = 24
  const laneBuckets = new Map(laneSpecs.map((l) => [l.id, []]))
  const fallbackLaneId = laneSpecs[0].id
  for (const f of features) {
    const preferredActor = f.actors[0]
    const targetLane = (preferredActor && laneBuckets.has(preferredActor))
      ? preferredActor
      : (laneBuckets.has(f.domain) ? f.domain : fallbackLaneId)
    laneBuckets.get(targetLane).push(f)
  }

  const lanes = []
  const flowNodes = []
  const flowNodeMap = new Map()
  let curY = pad

  laneSpecs.forEach((lane) => {
    const items = laneBuckets.get(lane.id) || []
    const byRank = new Map()
    for (const item of items) {
      const r = ranks.get(item.id) || 0
      if (!byRank.has(r)) byRank.set(r, [])
      byRank.get(r).push(item)
    }
    const maxStack = Math.max(1, ...Array.from(byRank.values()).map((arr) => arr.length))
    const laneH = lanePadY * 2 + maxStack * nodeH + Math.max(0, maxStack - 1) * nodeGapY
    const totalW = labelColW + (maxRank + 1) * nodeW + maxRank * colGap + pad * 2
    const palette = lane.palette || pickDomainPalette(lane.id)
    lanes.push({ id: lane.id, title: lane.title, shortTitle: truncateLabel(lane.title, 20), x: pad, y: curY, w: totalW, h: laneH, labelW: labelColW, palette })

    for (const [r, group] of byRank.entries()) {
      group.forEach((feat, stackIdx) => {
        const nx = pad + labelColW + 20 + r * (nodeW + colGap)
        const ny = curY + lanePadY + stackIdx * (nodeH + nodeGapY)
        const node = {
          id: feat.id, title: feat.title, shortTitle: truncateLabel(feat.title, 22),
          laneId: lane.id, rank: r, x: nx, y: ny, w: nodeW, h: nodeH,
          cx: nx + nodeW / 2, cy: ny + nodeH / 2,
          diffState: stateMap.get(feat.id) || 'context',
          isVirtual: Boolean(feat.isVirtual),
          palette,
        }
        flowNodes.push(node)
        flowNodeMap.set(feat.id, node)
      })
    }
    curY += laneH + 14
  })

  const flowEdges = []
  for (const [fromId, toId] of edgePairs) {
    const src = flowNodeMap.get(fromId)
    const dst = flowNodeMap.get(toId)
    if (!src || !dst) continue
    const x1 = src.x + src.w, y1 = src.cy, x2 = dst.x, y2 = dst.cy
    const dx = Math.max(28, Math.abs(x2 - x1) * 0.45)
    const edgeState = (src.diffState === 'added' || dst.diffState === 'added')
      ? 'added'
      : ((src.diffState === 'removed' || dst.diffState === 'removed')
          ? 'removed'
          : ((src.diffState !== 'context' || dst.diffState !== 'context') ? 'impacted' : 'context'))
    flowEdges.push({
      id: `flow:${fromId}->${toId}`, fromId, toId,
      pathD: `M ${x1} ${y1} C ${x1 + dx} ${y1}, ${x2 - dx} ${y2}, ${x2} ${y2}`,
      edgeState,
      isVirtual: Boolean(src.isVirtual || dst.isVirtual),
      impacted: edgeState !== 'context',
    })
  }

  return { width: Math.max(640, ...lanes.map((l) => l.w + pad)), height: Math.max(280, curY + pad), lanes, nodes: flowNodes, edges: flowEdges, flows: flowSummaries }
}

export function buildVisualModel({
  featureMap = {},
  diffOverlay = {},
  mode = 'architecture-map',
  title = '',
  briefSpec = null,
} = {}) {
  const overlay = computeDiffOverlay(featureMap, diffOverlay)
  const tree = layoutDomainTree(featureMap, overlay)
  const flow = layoutFlowDag(featureMap, overlay)
  const repoName = String(featureMap?.repoName || featureMap?.project || briefSpec?.repoName || '项目仓库').trim()
  const resolvedMode = mode === 'visual-brief' ? 'visual-brief' : 'architecture-map'
  const resolvedTitle = String(
    title || briefSpec?.title || (resolvedMode === 'visual-brief' ? `${repoName} — 实时规划简报` : `${repoName} — 架构全景图`)
  ).trim()

  const verdict = briefSpec?.verdict || {
    status: overlay.hasActiveDiff ? '有变更' : '已同步',
    tone: overlay.hasActiveDiff ? 'warn' : 'pass',
    summary: overlay.hasActiveDiff
      ? `新增 ${overlay.counts.added}、修改 ${overlay.counts.modified}、拟移除 ${overlay.counts.removed}、受波及 ${overlay.counts.impacted} 个模块。`
      : `共 ${tree.domains.length} 个域、${tree.nodes.length} 个模块，全部已同步。`,
  }

  const scopeChips = normArray(briefSpec?.scopeChips).length > 0
    ? normArray(briefSpec.scopeChips)
    : [`schema:${featureMap?.version >= 2 ? 'v2' : 'v1-compat'}`, `域:${tree.domains.length}`, `模块:${tree.nodes.length}`, `依赖:${tree.edges.length}`]

  const metrics = Array.isArray(briefSpec?.metrics) && briefSpec.metrics.length > 0
    ? briefSpec.metrics
    : [
        { label: '域', value: String(tree.domains.length) },
        { label: '模块', value: String(tree.nodes.length) },
        { label: '依赖', value: String(tree.edges.length) },
        { label: '新增', value: String(overlay.counts.added) },
        { label: '修改', value: String(overlay.counts.modified) },
        { label: '拟移除', value: String(overlay.counts.removed) },
        { label: '受波及', value: String(overlay.counts.impacted) },
      ]

  const walkthrough = Array.isArray(briefSpec?.walkthrough) && briefSpec.walkthrough.length > 0
    ? briefSpec.walkthrough.map((step, idx) => ({
        index: idx,
        targetId: String(step.targetId || tree.nodes[idx]?.id || '').trim(),
        title: String(step.title || `步骤 ${idx + 1}`).trim(),
        detail: String(step.detail || '').trim(),
      }))
    : tree.nodes.map((n, idx) => ({
        index: idx,
        targetId: n.id,
        title: n.title,
        detail: n.description || `${n.domainTitle || n.domain}（${n.modules.length} 个模块，${n.tests.length} 个测试）`,
      }))

  const prototypes = Array.isArray(briefSpec?.prototypes) ? briefSpec.prototypes : []
  const panels = [
    { id: 'panel-tree', title: '全景架构', promptHint: '核查领域边界与模块归属。' },
    { id: 'panel-flow', title: '业务流转', promptHint: '核查跨模块依赖关系与角色泳道。' },
    { id: 'panel-diff', title: '变更蓝图', promptHint: '核查新增、修改、拟移除及下游受波及模块。' },
    { id: 'panel-prototypes', title: '方案原型', promptHint: '核查沙盒原型预览与外部设计参考链接。' },
  ]

  return {
    schemaVersion: 2, mode: resolvedMode, repoName, title: resolvedTitle, verdict, scopeChips, metrics,
    overlayCounts: overlay.counts, hasActiveDiff: overlay.hasActiveDiff, tree, flow, walkthrough, prototypes,
    briefData: briefSpec?.briefData || null, panels,
  }
}
